function validate([nums, k, x]) {
  if (nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -50 || v > 50)) return 'Each value is an integer from -50 to 50.';
  if (!Number.isInteger(k) || k < 1 || k > nums.length) return 'k is between 1 and the length of nums.';
  if (!Number.isInteger(x) || x < 1 || x > k) return 'x is between 1 and k.';
  return null;
}

