function getSubarrayBeauty(nums, k, x) {
  const OFFSET = 50;
  const count = new Array(101).fill(0);
  const result = [];

  for (let right = 0; right < nums.length; right++) {
    count[nums[right] + OFFSET]++;
    const left = right - k + 1;
    if (left < 0) {
      continue;
    }
    let seen = 0;
    let beauty = 0;
    for (let value = -50; value < 0; value++) {
      seen += count[value + OFFSET];
      if (seen >= x) {
        beauty = value;
        break;
      }
    }
    result.push(beauty);
    count[nums[left] + OFFSET]--;
  }
  return result;
}

