function getSubarrayBeauty(nums, k, x) {
  const out = [];
  for (let start = 0; start + k <= nums.length; start++) {
    const negatives = nums.slice(start, start + k).filter(v => v < 0).sort((a, b) => a - b);
    out.push(negatives.length >= x ? negatives[x - 1] : 0);
  }
  return out;
}

