function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 10);
    const k = int(1, n);
    const x = int(1, k);
    const span = rand() < 0.5 ? 4 : 50;
    const bias = rand();
    const nums = Array.from({ length: n }, () => (rand() < bias ? -int(1, span) : int(0, span)));
    return [nums, k, x];
  }
  const n = 2000;
  const k = rand() < 0.5 ? int(1, 40) : int(1, n);
  const x = rand() < 0.7 ? int(1, Math.max(1, Math.floor(k / 2))) : int(1, k);
  const bias = 0.3 + rand() * 0.6;
  const nums = Array.from({ length: n }, () => (rand() < bias ? -int(1, 50) : int(0, 50)));
  return [nums, k, x];
}
